const VAGUES = [THEMES, THEMES2, THEMES3, THEMES4, THEMES5];

/* ================================================================== */
/* Écriture du CSV                                                     */
/* ================================================================== */

const HEAD = ['id', 'theme', 'categorie', 'difficulte', 'type', 'question', 'reponse', 'choix2', 'choix3', 'choix4',
  'explication', 'indices', 'media_url', 'media_debut', 'media_duree', 'actif', 'utilisations', 'epoque', 'anecdote'];

const cell = v => {
  v = v === undefined || v === null ? '' : String(v);
  return /[",\n;]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
};
const norm = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');

function parseCsv(text) {
  const rows = []; let cur = [], f = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += c; }
    else if (c === '"') q = true;
    else if (c === ',') { cur.push(f); f = ''; }
    else if (c === '\n') { cur.push(f); rows.push(cur); cur = []; f = ''; }
    else if (c !== '\r') f += c;
  }
  if (f || cur.length) { cur.push(f); rows.push(cur); }
  const head = rows[0];
  return rows.slice(1).filter(r => r.length === head.length)
    .map(r => Object.fromEntries(head.map((h, i) => [h, r[i]])));
}

const AUTRES = ['questions', 'questions-repliques', 'questions-blindtest', 'questions-dates',
  'questions-devinettes', 'questions-citations', 'questions-nouveaux-themes'];
const dejaPosees = new Set();
const comptes = {};
AUTRES.forEach(f => {
  const chemin = path.join(ROOT, 'supabase/' + f + '.csv');
  if (!fs.existsSync(chemin)) return;
  parseCsv(fs.readFileSync(chemin, 'utf8')).forEach(r => {
    dejaPosees.add(norm(r.question));
    comptes[r.theme] = (comptes[r.theme] || 0) + 1;
  });
});

const lignes = [];
const vues = new Set();
const soucis = [];
let n = 2800;

// Plusieurs vagues d'écriture : un même thème peut revenir d'une vague à l'autre.
VAGUES.forEach(VAGUE => {
Object.keys(VAGUE).forEach(theme => {
  Object.keys(VAGUE[theme]).forEach(cat => {
    VAGUE[theme][cat].forEach(([q, rep, faux, diff, expl]) => {
      if (!q || !rep) throw new Error('question incomplète : ' + q);
      if (!faux || faux.length !== 3) throw new Error('il faut 3 mauvaises réponses : ' + q);
      if (!expl || expl.length < 45) throw new Error('explication trop courte : ' + q);
      if (!(diff >= 1 && diff <= 5)) throw new Error('difficulté hors bornes : ' + q);
      // dans les deux cas on écarte la question : sinon elle serait écrite deux fois
      if (vues.has(norm(q))) { soucis.push('en double ici : ' + q); return; }
      if (dejaPosees.has(norm(q))) { soucis.push('déjà en banque : ' + q); return; }
      vues.add(norm(q));
      if (new Set([rep].concat(faux).map(norm)).size !== 4) throw new Error('propositions en double : ' + q);
      lignes.push(['Q' + (n++), theme, cat, diff, 'QCM', q, rep, faux[0], faux[1], faux[2],
        expl, '', '', 0, 15, 'oui', 0, '', '']);
      comptes[theme] = (comptes[theme] || 0) + 1;
    });
  });
});
});

if (soucis.length) {
  console.log('⚠️  ' + soucis.length + ' question(s) écartée(s) :');
  soucis.forEach(x => console.log('   ' + x));
}

fs.writeFileSync(path.join(ROOT, 'supabase/questions-complement.csv'),
  [HEAD.join(',')].concat(lignes.map(l => l.map(cell).join(','))).join('\n'));

console.log(`${lignes.length} questions écrites → supabase/questions-complement.csv (Q2800 à Q${n - 1})\n`);
console.log('Où en sont les nouveaux thèmes (objectif : 100) :');
['Mythologie & légendes', 'Espace & astronomie', 'Corps humain & santé', 'Inventions & technologie',
  'Séries & télévision', 'Marques & publicité', 'Contes & dessins animés', 'Transports',
  'Citations & expressions'].forEach(t => {
  const c = comptes[t] || 0;
  console.log(`  ${String(c).padStart(3)} / 100  ${t}${c >= 100 ? '  ✅' : '   (il en manque ' + (100 - c) + ')'}`);
});
